// stringUtils.js
export const WERSJA = "1.0.0";
export function capitalize(str) { return str.charAt(0).toUpperCase() + str.slice(1); }
export default function odwroc(str) { return [...str].reverse().join(""); }

// inny-plik.js
import * as StrUtils from "./stringUtils.js";
console.log(StrUtils.WERSJA);             // "1.0.0"
console.log(StrUtils.capitalize("test")); // "Test"
console.log(StrUtils.default("test"));    // "tset" - eksport domyslny pod kluczem 'default'

// mathUtils.js
export const PI = 3.14159;
export default function pomnoz(a, b) { return a * b; }

// inny-plik.js
import * as MathAll from "./mathUtils.js";
console.log(MathAll.PI);          // 3.14159
console.log(MathAll.default(5, 5)); // 25

// mathUtils.js
export function dodaj(a, b) { return a + b; }
export function odejmij(a, b) { return a - b; }

// inny-plik.js
import * as MatObiekt from "./mathUtils.js";
console.log(MatObiekt.dodaj(10, 20));   // 30
console.log(MatObiekt.odejmij(10, 20)); // -10

// import * as MathUtils from './mathUtils.js' tworzy OBIEKT MathUtils,
// niezaleznie od tego, CZYM byl eksport domyslny w pliku zrodlowym
// (funkcja, klasa, zmienna). Sam obiekt MathUtils nigdy nie jest
// funkcja - jest 'kontenerem' zawierajacym WSZYSTKIE eksporty pliku
// jako swoje pola.
//
// import * as MathUtils from "./mathUtils.js";
// MathUtils(3, 3); // TypeError: MathUtils is not a function
// MathUtils.default(3, 3); // POPRAWNIE - eksport domyslny jest polem 'default'

// Kolory.js
export const CZERWONY = "#f00";
export const ZIELONY = "#0f0";
export const NIEBIESKI = "#00f";

// inny-plik.js
import * as KolorySet from "./Kolory.js";
console.log(KolorySet.CZERWONY);  // "#f00"
console.log(KolorySet.ZIELONY);   // "#0f0"
console.log(KolorySet.NIEBIESKI); // "#00f"

// Namespace import jest uzywany rzadziej, poniewaz:
// 1. Import nazwany/domyslny z konkretnie wypisanymi nazwami jest
//    CZYTELNIEJSZY - od razu widac, jakie DOKLADNIE elementy z modulu
//    sa uzywane w danym pliku, bez potrzeby przeszukiwania calego kodu.
// 2. Narzedzia 'budujace' aplikacje (np. bundlery jak Vite/Webpack)
//    moga lepiej zoptymalizowac koncowy rozmiar aplikacji przez
//    'tree-shaking' (usuwanie nieuzywanego kodu), gdy widza DOKLADNIE,
//    ktore konkretne eksporty sa importowane - namespace import utrudnia
//    te analize, bo teoretycznie MOZE byc uzyty KAZDY eksport modulu.

// Formularz.js
export default function validate(dane) {
  return Object.keys(dane).length > 0;
}
export const BLEDY_TEKST = "Nieprawidlowe dane";

// inny-plik.js
import * as FormularzUtils from "./Formularz.js";
console.log(FormularzUtils.default({}));       // false
console.log(FormularzUtils.BLEDY_TEKST);        // "Nieprawidlowe dane"

// Kolory.js
export const czerwony = "#f00";
export const zielony = "#0f0";

// main.js
import * as Kolory from "./Kolory.js";
console.log(Kolory.czerwony, Kolory.zielony); // -> #f00 #0f0

// Waga.js
export default function przelicz(kg) {
  return kg * 2.20462;
}
export const jednostka = "funty";

// main.js
import * as Waga from "./Waga.js";
console.log(Math.round(Waga.default(10)), Waga.jednostka); // -> 22 funty

// Osoba.js
export default class Osoba {
  constructor(imie) {
    this.imie = imie;
  }
}

// main.js
import * as M from "./Osoba.js";
console.log(typeof M);
const o = new M.default("Ala");
console.log(o.imie); // -> "object" potem "Ala"

// a.js
export const x = 1;

// main.js
import * as M from "./a.js";
try {
  M.x = 100;
} catch (e) {
  console.log(e.name); // -> "TypeError"
}
// Obiekt namespace jest tylko do odczytu - kazda proba przypisania
// do jego pola konczy sie TypeError.

// Matematyka.js
export function dodaj(a, b) { return a + b; }
export function odejmij(a, b) { return a - b; }
export default function pomnoz(a, b) { return a * b; }

// main.js
import * as M from "./Matematyka.js";
console.log(M.dodaj(10, 5) + M.odejmij(10, 5) + M.default(10, 5)); // -> 65

// Ustawienia.js
export default { motyw: "jasny" };

// main.js
import * as M from "./Ustawienia.js";
M.default.motyw = "ciemny";
console.log(M.default.motyw); // -> "ciemny" - mutacja WEWNATRZ obiektu dziala

// Slownik.js
export const pies = "dog";
export const kot = "cat";
export const ptak = "bird";
export const ryba = "fish";

// main.js
import * as Slownik from "./Slownik.js";
console.log(Object.keys(Slownik).length); // -> 4

// Temperatura.js
export function celsjuszNaFahrenheit(c) {
  return (c * 9) / 5 + 32;
}
export default 0;

// main.js
import * as T from "./Temperatura.js";
console.log(T.celsjuszNaFahrenheit(T.default)); // -> 32

// Zwierze.js
export class Pies {
  szczekaj() { return "hau"; }
}
export class Kot {
  miauczy() { return "miau"; }
}

// main.js
import * as Zoo from "./Zwierze.js";
const pies = new Zoo.Pies();
const kot = new Zoo.Kot();
console.log(pies.szczekaj(), kot.miauczy()); // -> hau miau

// Statystyka.js
export function suma(t) {
  return t.reduce((s, x) => s + x, 0);
}
export function srednia(t) {
  return suma(t) / t.length;
}

// main.js
import * as Stat from "./Statystyka.js";
console.log(Stat.suma([2, 4, 6]), Stat.srednia([2, 4, 6])); // -> 12 4

// Fabryka.js
let ostatnie = 0;
export default function stworzId() {
  ostatnie++;
  return ostatnie;
}
export function reset() {
  ostatnie = 0;
}

// main.js
import * as F from "./Fabryka.js";
console.log(F.default(), F.default());
F.reset();
console.log(F.default()); // -> 1 2 potem 1

// Kolejka.js
export class Kolejka {
  el = [];
  dodaj(x) {
    this.el.push(x);
  }
  pobierz() {
    return this.el.shift();
  }
}

// main.js
import * as M from "./Kolejka.js";
const k = new M.Kolejka();
k.dodaj("a");
k.dodaj("b");
console.log(k.pobierz(), k.el.length); // -> "a" 1

// Waluty.js
export const pln = 1;
export const eur = 4.3;
export const usd = 4.0;

// main.js
import * as Kursy from "./Waluty.js";
for (const k in Kursy) {
  console.log(k, Kursy[k]);
}
// -> pln 1
// -> eur 4.3
// -> usd 4

// Sekwencja.js
export default function* liczby(limit) {
  for (let i = 1; i <= limit; i++) yield i;
}
export const limitDomyslny = 3;

// main.js
import * as Seq from "./Sekwencja.js";
console.log([...Seq.default(Seq.limitDomyslny)]); // -> [1, 2, 3]

// Logger.js
export function info(msg) {
  return "[i] " + msg;
}
export function blad(msg) {
  return "[e] " + msg;
}

// main.js
import * as Log1 from "./Logger.js";
import * as Log2 from "./Logger.js";
console.log(Log1 === Log2, Log1.info("start")); // -> true "[i] start"

// Historia.js
export let stan = "pusta";
export function zmienStan(nowy) {
  stan = nowy;
}

// main.js
import * as H from "./Historia.js";
H.zmienStan("aktywna");
console.log(H.stan); // -> "aktywna"

// Konwersje.js
export function metryNaStopy(m) {
  return m * 3.281;
}
export function stopyNaMetry(s) {
  return s / 3.281;
}

// main.js
import * as Konw from "./Konwersje.js";
console.log(Math.round(Konw.metryNaStopy(10)), Math.round(Konw.stopyNaMetry(10))); // -> 33 3

// Rejestr.js
export default class Rejestr {
  wpisy = [];
  dodaj(wpis) {
    this.wpisy.push(wpis);
    return this;
  }
}

// main.js
import * as M from "./Rejestr.js";
const r = new M.default();
r.dodaj("a").dodaj("b").dodaj("c");
console.log(r.wpisy.length); // -> 3

// Tlumaczenia.js
export const pl = { czesc: "czesc" };
export const en = { czesc: "hello" };

// main.js
import * as I18n from "./Tlumaczenia.js";
console.log(I18n.pl.czesc, I18n.en.czesc); // -> czesc hello

// Uprawnienia.js
export function czyAdmin(rola) {
  return rola === "admin";
}
export function czyGosc(rola) {
  return rola === "gosc";
}

// main.js
import * as Uprawnienia from "./Uprawnienia.js";
console.log(Uprawnienia.czyAdmin("admin"), Uprawnienia.czyGosc("admin")); // -> true false

// Zamowienie.js
export default function obliczTotal(pozycje) {
  return pozycje.reduce((s, p) => s + p, 0);
}
export const waluta = "zl";

// main.js
import * as Zam from "./Zamowienie.js";
console.log(Zam.default([10, 20]) + " " + Zam.waluta); // -> "30 zl"

// Walidacja.js
export function jestEmailem(s) {
  return s.includes("@");
}

// main.js
import * as V from "./Walidacja.js";
console.log(V.jestEmailem("test@test.com"), V.jestEmailem("zlyemail")); // -> true false

// Godziny.js
export function jestOtwarte(godzina) {
  return godzina >= 9 && godzina <= 17;
}

// main.js
import * as Sklep from "./Godziny.js";
console.log(Sklep.jestOtwarte(8), Sklep.jestOtwarte(12), Sklep.jestOtwarte(18));
// -> false true false

